import { data, takaro } from '@takaro/helpers';

async function main() {
  const { gameServerId, module } = data;

  const moduleConfig = module.userConfig || {};
  const discordChannelId = moduleConfig.discordChannelId;
  const cronIntervalMinutes = Number(moduleConfig.cronIntervalMinutes || 5);

  if (!discordChannelId) {
    console.log('Discord channel ID not configured');
    return;
  }

  // 1. Pobieramy listę graczy online z komendy lp
  const lpResult = await takaro.gameserver.gameServerControllerExecuteCommand(gameServerId, {
    command: 'lp'
  });

  const output = lpResult.data.data.rawResult;
  const lines = output ? output.split('\n') : [];
  const onlinePlayerIds = new Set();
  const onlinePlayersFromCmd = [];

  for (const line of lines) {
    const nameMatch = line.match(/id=\d+,\s*([^,]+),/);
    const deathsMatch = line.match(/deaths=(\d+)/i);
    const zombiesMatch = line.match(/zombies=(\d+)/i);
    const levelMatch = line.match(/level=(\d+)/i);
    const scoreMatch = line.match(/score=(\d+)/i);

    // Obsługa Steam oraz konsol (Xbox, EOS i inne unikalne identyfikatory)
    const steamIdMatch = line.match(/Steam_(\d+)/);
    const platformIdMatch = line.match(/(?:Xbl_|EOS_|PSN_|PlatformId_)?([a-zA-Z0-9_-]{16,})/);

    let playerId = null;
    if (steamIdMatch) {
      playerId = steamIdMatch[1];
    } else if (platformIdMatch) {
      const potentialId = line.match(/(?:Steam_|Xbl_|EOS_|PSN_)([a-zA-Z0-9_-]+)/);
      playerId = potentialId ? potentialId[1] : platformIdMatch[1];
    }

    if (nameMatch && playerId) {
      onlinePlayerIds.add(playerId);
      onlinePlayersFromCmd.push({
        playerId: playerId,
        name: nameMatch[1].trim(),
        deaths: deathsMatch ? parseInt(deathsMatch[1]) : 0,
        zombies: zombiesMatch ? parseInt(zombiesMatch[1]) : 0,
        level: levelMatch ? parseInt(levelMatch[1]) : 0,
        score: scoreMatch ? parseInt(scoreMatch[1]) : 0
      });
    }
  }

  // 2. Pobieramy bazę danych z Takaro (unikalny klucz dla kanału 1)
  const variableSearch = await takaro.variable.variableControllerSearch({
    filters: {
      key: ['leaderboard_season_data_1'],
      gameServerId: [gameServerId]
    }
  });

  let storedPlayers = {};
  let leaderboardDataVarId = null;

  if (variableSearch.data.data.length > 0) {
    const foundVar = variableSearch.data.data[0];
    leaderboardDataVarId = foundVar.id;
    try {
      storedPlayers = JSON.parse(foundVar.value);
    } catch (error) {
      storedPlayers = {};
    }
  }

  // 3. Aktualizujemy statystyki graczy online z precyzyjnym czasem
  const nowTimestamp = Date.now();

  if (onlinePlayersFromCmd.length > 0) {
    for (const player of onlinePlayersFromCmd) {
      const existing = storedPlayers[player.playerId] || {};

      let minutesToAdd = cronIntervalMinutes;

      if (existing.lastSeenTimestamp) {
        const diffMs = nowTimestamp - existing.lastSeenTimestamp;
        const diffMins = Math.round(diffMs / 60000);
        minutesToAdd = Math.min(Math.max(diffMins, 1), cronIntervalMinutes * 1.5);
      }

      const currentSessionMinutes = (existing.currentSessionMinutes || 0) + minutesToAdd;
      const longestSession = Math.max(existing.longestSession || 0, currentSessionMinutes);
      const totalPlaytime = (existing.totalPlaytime || 0) + minutesToAdd;

      storedPlayers[player.playerId] = {
        steamId: player.playerId,
        name: player.name,
        deaths: Math.max(existing.deaths || 0, player.deaths),
        zombies: Math.max(existing.zombies || 0, player.zombies),
        level: Math.max(existing.level || 0, player.level),
        score: Math.max(existing.score || 0, player.score),
        currentSessionMinutes: currentSessionMinutes,
        longestSession: longestSession,
        totalPlaytime: totalPlaytime,
        lastSeenTimestamp: nowTimestamp
      };
    }

    for (const playerId of Object.keys(storedPlayers)) {
      if (!onlinePlayerIds.has(playerId)) {
        storedPlayers[playerId].currentSessionMinutes = 0;
        storedPlayers[playerId].lastSeenTimestamp = null;
      }
    }
  } else {
    for (const playerId of Object.keys(storedPlayers)) {
      storedPlayers[playerId].currentSessionMinutes = 0;
      storedPlayers[playerId].lastSeenTimestamp = null;
    }
  }

  const allPlayers = Object.values(storedPlayers);
  if (allPlayers.length > 0) {
    const storedDataJson = JSON.stringify(storedPlayers);

    if (leaderboardDataVarId) {
      await takaro.variable.variableControllerUpdate(leaderboardDataVarId, {
        value: storedDataJson
      });
    } else {
      await takaro.variable.variableControllerCreate({
        key: 'leaderboard_season_data_1',
        value: storedDataJson,
        moduleId: data.module.moduleId,
        gameServerId: gameServerId
      });
    }
  }

  // Top 8 miejsc
  const topZombieKills = [...allPlayers].sort((a, b) => (b.zombies || 0) - (a.zombies || 0)).slice(0, 8);
  const topLevelSorted = [...allPlayers].sort((a, b) => (b.level || 0) - (a.level || 0)).slice(0, 8);
  const topScore = [...allPlayers].sort((a, b) => (b.score || 0) - (a.score || 0)).slice(0, 8);
  const topLongestSession = [...allPlayers].sort((a, b) => (b.longestSession || 0) - (a.longestSession || 0)).slice(0, 8);
  const sortedTotalPlaytime = [...allPlayers].sort((a, b) => (b.totalPlaytime || 0) - (a.totalPlaytime || 0)).slice(0, 8);
  const sortedDeathsClean = [...allPlayers].sort((a, b) => (b.deaths || 0) - (a.deaths || 0)).slice(0, 8);

  const getPositionPrefix = (i) => {
    if (i === 0) return '🥇';
    if (i === 1) return '🥈';
    if (i === 2) return '🥉';
    if (i === 3) return '4️⃣';
    if (i === 4) return '5️⃣';
    if (i === 5) return '6️⃣';
    if (i === 6) return '7️⃣';
    if (i === 7) return '8️⃣';
    return `${i + 1}.`;
  };

  function formatPlaytime(totalMinutes) {
    if (!totalMinutes || totalMinutes === 0) return '0 min';
    const hours = Math.floor(totalMinutes / 60);
    const mins = totalMinutes % 60;
    if (hours > 0) {
      return `${hours}h ${mins}m`;
    }
    return `${mins} min`;
  }

  function formatTableList(list, statKey, unitLabel) {
    if (!list || list.length === 0 || list.every(p => (p[statKey] || 0) === 0)) {
      return '```\n          ---  brak danych  ---\n```';
    }

    const boxWidth = 32;

    const rows = list.map((p, i) => {
      const pos = getPositionPrefix(i);
      const name = String(p.name || 'Unknown').slice(0, 18);
      const valStr = (statKey === 'longestSession' || statKey === 'totalPlaytime')
        ? formatPlaytime(p[statKey])
        : `${(p[statKey] || 0).toLocaleString()} ${unitLabel}`.trim();

      const leftPart = `${pos} ${name}`;
      const rightPart = valStr;

      let spaceCount = Math.max(2, boxWidth - (leftPart.length + rightPart.length));

      // Dodatkowa spacja tylko dla wartości w miejscach 4-8 (indeksy 3 do 7), żeby przesunąć wyłącznie liczbę/wynik w prawo
      if (i >= 3) {
        spaceCount += 1;
      }

      const rowLine = leftPart + ' '.repeat(spaceCount) + rightPart;

      return rowLine;
    });

    return `\`\`\`\n${rows.join('\n')}\n\`\`\``;
  }

  // Czas lokalny CEST
  const now = new Date();
  now.setHours(now.getHours() + 2);
  const timeString = now.toISOString().slice(11, 16);

  const embed = {
    color: 0xFF6B35,
    fields: [
      {
        name: '💥 .......... POGROMCY ZOMBIE .......... 💥',
        value: formatTableList(topZombieKills, 'zombies', 'zabójstw'),
        inline: false
      },
      {
        name: '🌱 ........ NAJWYŻSZE POZIOMY ........ 🌱',
        value: formatTableList(topLevelSorted, 'level', 'poz.'),
        inline: false
      },
      {
        name: '💎 ......... PUNKTACJA GRACZY ......... 💎',
        value: formatTableList(topScore, 'score', 'pkt'),
        inline: false
      },
      {
        name: '⏳ .......... NAJDŁUŻSZA SESJA .......... ⏳',
        value: formatTableList(topLongestSession, 'longestSession', ''),
        inline: false
      },
      {
        name: '⏰ ........ SEZONOWY CZAS GRY ........ ⏰',
        value: formatTableList(sortedTotalPlaytime, 'totalPlaytime', ''),
        inline: false
      },
      {
        name: '💀 ......... NAJWIĘCEJ ZGONÓW ......... 💀',
        value: formatTableList(sortedDeathsClean, 'deaths', 'zgonów'),
        inline: false
      }
    ],
    footer: {
      text: `Aktualizacja co ${cronIntervalMinutes} minut.                   Ostatnia: ${timeString}`
    }
  };

  // 4. Pobieramy ID poprzedniej wiadomości leaderboardu z bazy Takaro
  const messageIdSearch = await takaro.variable.variableControllerSearch({
    filters: {
      key: ['leaderboard_season_message_id_1'],
      gameServerId: [gameServerId]
    }
  });

  let messageId = null;
  let variableRecordId = null;

  if (messageIdSearch.data.data.length > 0) {
    const foundMsgVar = messageIdSearch.data.data[0];
    messageId = foundMsgVar.value;
    variableRecordId = foundMsgVar.id;
  }

  // Edycja istniejącej wiadomości lub wysłanie nowej, jeśli jej nie ma
  if (messageId) {
    try {
      await takaro.discord.discordControllerUpdateMessage(discordChannelId, messageId, {
        embed: embed
      });
    } catch (error) {
      console.log('Nie udało się edytować wiadomości, wysyłam nową:', error.message);
      const newMessage = await takaro.discord.discordControllerSendMessage(discordChannelId, {
        embed: embed
      });
      const newMsgId = newMessage.data.data.id;

      if (variableRecordId) {
        await takaro.variable.variableControllerUpdate(variableRecordId, {
          value: newMsgId
        });
      } else {
        await takaro.variable.variableControllerCreate({
          key: 'leaderboard_season_message_id_1',
          value: newMsgId,
          moduleId: data.module.moduleId,
          gameServerId: gameServerId
        });
      }
    }
  } else {
    const newMessage = await takaro.discord.discordControllerSendMessage(discordChannelId, {
      embed: embed
    });
    const newMsgId = newMessage.data.data.id;

    if (variableRecordId) {
      await takaro.variable.variableControllerUpdate(variableRecordId, {
        value: newMsgId
      });
    } else {
      await takaro.variable.variableControllerCreate({
        key: 'leaderboard_season_message_id_1',
        value: newMsgId,
        moduleId: data.module.moduleId,
        gameServerId: gameServerId
      });
    }
  }
}

await main();
